import i18n from "i18next";
import { initReactI18next } from "react-i18next";
import LanguageDetector from "i18next-browser-languagedetector";

// Імпортуємо ресурси для перекладу
import translationEN from "./locales/en/translation.json";
import translationUK from "./locales/uk/translation.json";

// Ресурси для кожної мови
const resources = {
  en: {
    translation: translationEN,
  },
  uk: {
    translation: translationUK,
  },
};

// Ініціалізація i18n з покращеною конфігурацією для React 19
const initI18n = async () => {
  await i18n
    // Виявлення мови з локальних налаштувань браузера
    .use(LanguageDetector)
    // Ініціалізація модуля react-i18next
    .use(initReactI18next)
    // Ініціалізація i18next
    .init({
      resources,
      fallbackLng: "uk", // Мова за замовчуванням
      debug: false, // Вимкнути debug щоб уникнути зайвих повідомлень

      interpolation: {
        escapeValue: false, // Не екранувати HTML
      },

      // Опції для визначення мови
      detection: {
        order: ["localStorage", "navigator"], // Спочатку перевіряємо localStorage, потім браузер
        lookupLocalStorage: "tetracore-hub-language", // Ключ для localStorage
        caches: ["localStorage"], // Зберігати вибір у localStorage
      },

      // Конфігурація для React 19
      react: {
        useSuspense: false, // Не використовувати React Suspense
        bindI18n: "languageChanged", // Прив'язка тільки до зміни мови
        bindI18nStore: false, // Не прив'язуватися до store
        transEmptyNodeValue: "", // Порожнє значення для пустих нод
        transSupportBasicHtmlNodes: true, // Підтримка базових HTML нод
        transKeepBasicHtmlNodesFor: ["br", "strong", "i", "p"], // Список дозволених HTML тегів
      },

      // Додаткові опції стабільності
      lng: "uk", // Явно встановлюємо мову
      keySeparator: false, // Вимкнути сепаратор ключів
      nsSeparator: false, // Вимкнути сепаратор namespace
      returnEmptyString: false, // Не повертати пусті рядки
      returnNull: false, // Не повертати null
      returnObjects: false, // Не повертати об'єкти
    });
};

// Ініціалізуємо i18n
initI18n().catch(console.error);

export default i18n;
